package toolchain_test

import (
	"errors"
	"os"
	"path/filepath"
	"testing"
	"testing/fstest"

	"go.dokimi.dev/assert"
	"go.dokimi.dev/assert/files"

	"go.dokimi.dev/eidos/core/internal/coretest"
	"go.dokimi.dev/eidos/core/toolchain"
)

// absentToolchain is the reason of the fixture adapter for a toolchain
// that the machine lacks.
const absentToolchain = "scriptedc is not on PATH"

// These constants are the path of a source file and its content, the
// content of a source file at the path of the generated file, and a
// directory that no case creates.
const (
	sourceFile   = "src/row.s"
	sourceBody   = "source\n"
	replacedBody = "stale\n"
	missingDir   = "missing"
)

// The layout contract and the CI rule let a satellite run the same suite
// on a machine with the toolchain and on one without it.
func TestGate(t *testing.T) {
	t.Parallel()

	t.Run("Prepare", func(t *testing.T) {
		t.Parallel()

		t.Run("returns the laid-out directory with a cleanup that removes it", func(t *testing.T) {
			t.Parallel()

			var (
				dir string
				saw map[string]string
			)
			got, done := toolchain.Prepare(t, scripted{laidOut: &dir, sawFiles: &saw}, output())
			assert.Equal(t, got, dir, "the assertion receives the directory that the adapter wrote")
			files.IsDir(t, got, "the directory exists while the check runs")
			assert.Equal(t, saw, map[string]string{generatedFile: generatedBody},
				"the adapter receives the generated bytes")
			done()
			files.Absent(t, got, "the cleanup removes the scratch project")
		})

		tests := []struct {
			name string
			give fstest.MapFS
			want map[string]string
		}{
			{
				name: "lays out each file of the sources",
				give: fstest.MapFS{sourceFile: {Data: []byte(sourceBody)}},
				want: map[string]string{generatedFile: generatedBody, sourceFile: sourceBody},
			},
			{
				name: "lays out a generated file in place of the source file at its path",
				give: fstest.MapFS{generatedFile: {Data: []byte(replacedBody)}},
				want: map[string]string{generatedFile: generatedBody},
			},
		}
		for _, tt := range tests {
			t.Run(tt.name, func(t *testing.T) {
				t.Parallel()

				var saw map[string]string
				g := output()
				g.Sources = tt.give
				_, done := toolchain.Prepare(t, scripted{sawFiles: &saw}, g)
				defer done()
				assert.Equal(t, saw, tt.want, "the adapter receives the files of the sources with the generated files")
			})
		}

		t.Run("records sources that do not read", func(t *testing.T) {
			t.Parallel()

			g := output()
			g.Sources = os.DirFS(filepath.Join(t.TempDir(), missingDir))
			var dir string
			got := assert.Rejects(t, "sources that do not read fail the check", func(tb assert.TB) {
				var done func()
				dir, done = toolchain.Prepare(tb, scripted{}, g)
				done()
			})
			assert.Equal(t, dir, "", "nothing was laid out")
			assert.Equal(t, coretest.Contracts(got), []string{"scripted: the sources of the fixture read"},
				"the failure names the step")
		})

		t.Run("records a layout the language refused", func(t *testing.T) {
			t.Parallel()

			refusal := errors.New("no room")
			var dir string
			got := assert.Rejects(t, "a refused layout fails the check", func(tb assert.TB) {
				var done func()
				dir, done = toolchain.Prepare(tb, scripted{layoutErr: refusal}, output())
				done()
			})
			assert.Equal(t, dir, "", "nothing was laid out")
			assert.Equal(t, coretest.Contracts(got),
				[]string{"scripted: the generated output lays out for the toolchain"}, "the failure names the step")
			reason, stated := got[0].Got()
			assert.True(t, stated, "the record has the error")
			assert.Equal(t, reason, any(refusal), "the error is the reason of the language")
		})

		t.Run("records a failure for a missing adapter", func(t *testing.T) {
			t.Parallel()

			var dir string
			got := assert.Rejects(t, "a missing adapter fails the check", func(tb assert.TB) {
				var done func()
				dir, done = toolchain.Prepare(tb, nil, output())
				done()
			})
			assert.Equal(t, dir, "", "nothing was laid out")
			assert.Equal(t, coretest.Contracts(got), []string{"toolchain: an adapter lays the fixture out"},
				"a fixture with nothing to lay it out proves nothing")
		})
	})
}

// The CI rule reads a variable of the process, so it runs on its own and
// not beside the parallel cases.
func TestRequiredInCI(t *testing.T) {
	t.Run("reports whether the CI variable is set", func(t *testing.T) {
		t.Setenv("CI", "")
		assert.False(t, toolchain.RequiredInCI(), "an unset variable runs as local")
		t.Setenv("CI", "true")
		assert.True(t, toolchain.RequiredInCI(), "a true variable runs as CI")
	})

	t.Run("reports false for a false boolean", func(t *testing.T) {
		for _, off := range []string{"false", "0", "FALSE"} {
			t.Setenv("CI", off)
			assert.False(t, toolchain.RequiredInCI(), "CI="+off+" runs as local")
		}
		t.Setenv("CI", "woodpecker")
		assert.True(t, toolchain.RequiredInCI(), "the name of a runner runs as CI")
	})

	t.Run("skips a missing toolchain locally with the reason of the adapter", func(t *testing.T) {
		t.Setenv("CI", "")
		s := &gateTB{Recorder: assert.NewRecorder()}
		assert.False(t, toolchain.Require(s, scripted{absent: absentToolchain}), "nothing can run without it")
		assert.Contains(t, s.skipped, absentToolchain, "the skip contains the reason of the adapter")
		assert.Contains(t, s.skipped, "required in CI", "the skip contains the place that requires the check")
		assert.Empty(t, s.Failures(), "a missing toolchain is not a local failure")
	})

	t.Run("records a missing toolchain in CI", func(t *testing.T) {
		t.Setenv("CI", "true")
		s := &gateTB{Recorder: assert.NewRecorder()}
		assert.False(t, toolchain.Require(s, scripted{absent: absentToolchain}), "nothing can run without it")
		assert.Equal(t, coretest.Contracts(s.Failures()),
			[]string{"scripted: the toolchain CI requires is present: " + absentToolchain},
			"the failure has the reason of the adapter")
		assert.Equal(t, s.skipped, "", "the gate skips nothing")
	})
}
